// vulnerabilities.ts
// Dataset offline para la herramienta "Vulnerabilidades IAM/SOC" de VaultNotes.
// 100% offline — este dataset alimenta VulnerabilityExplorerTool.tsx.
//
// Cobertura: JWT/OAuth/SAML, Active Directory (Kerberos, delegación, AD CS
// ESC1-ESC16, relay), Cloud IAM (AWS/Azure/GCP/K8s/Snowflake), Privilege
// Escalation (Windows privileges, Linux caps/containers), evasión SOC
// (AMSI/ETW/LOLBins/BYOVD/AiTM), movimiento lateral, persistencia (incl.
// UEFI, cloud infra y Office) y governance IAM (JML, PIM, access reviews).
//
// IDs: <CATEGORÍA>-<NNN>. No usar `export default`.
// Las detecciones son ejemplos de partida: ajústalos a tu entorno
// (nombres de tablas, tenants, naming conventions).

export type VulnerabilityCategory =
  | 'IAM' | 'AD' | 'Auth' | 'Cloud_IAM' | 'SOC_Evasion'
  | 'PrivEsc' | 'LateralMovement' | 'Persistence';

export type VulnerabilitySeverity = 'Critical' | 'High' | 'Medium' | 'Low';

export interface VulnerabilityInfo {
  id: string;
  nombre: string;
  categoria: VulnerabilityCategory;
  severidad: VulnerabilitySeverity;
  cve_ejemplo?: string[];
  mitre_attack: string[];
  descripcion_tecnica: string;
  impacto_iam_soc: string;
  vector_ataque: string[];
  deteccion: { kql?: string; spl?: string; sigma?: string; win_event_ids?: number[] };
  mitigacion_hardening: string[];
  parcheo_remediacion: string[];
  referencias: string[];
}

